mapper.select:
SELECT DISTINCT item.issue_group_id FROM tb_ai_log_ai_task_item item JOIN tb_ai_log_analysis_task analysis ON analysis.id = item.analysis_task_id WHERE item.issue_group_id IN
#{groupId}
AND item.rerun_operation_id IS NULL AND analysis.log_date = #{logDate}

SELECT * FROM tb_ai_log_ai_task_item
WHERE ai_task_id = #{taskId} AND issue_group_id = #{issueGroupId}
ORDER BY id DESC LIMIT 1 FOR UPDATE

SELECT item.id AS itemId, item.ai_task_id AS aiTaskId, item.issue_group_id AS issueGroupId, task.provider_code AS providerCode, task.model_code AS modelCode, item.attempt_count AS attemptCount, item.max_attempts AS maxAttempts FROM tb_ai_log_ai_task_item item JOIN tb_ai_log_ai_task task ON task.id = item.ai_task_id WHERE item.ai_task_id = #{taskId} AND item.id IN
#{itemId}
AND task.status IN ('WAITING','RUNNING') AND item.status = 'WAITING' AND item.rerun_status IS NULL AND item.attempt_count < item.max_attempts AND (item.lease_until IS NULL OR item.lease_until < #{now}) AND (item.next_retry_time IS NULL OR item.next_retry_time <= #{now}) ORDER BY item.id ASC

mapper.update:
UPDATE tb_ai_log_ai_task_item
SET lease_until = #{leaseUntil},
    update_time = #{now}
WHERE id = #{itemId}
  AND claim_token = #{claimToken}
  AND status = 'RUNNING'

UPDATE tb_ai_log_ai_task_item item
SET item.blame_author_name = #{result.authorName},
    item.blame_author_time = #{result.authorTime}
WHERE item.id = #{itemId}
  AND item.claim_token = #{claimToken}
  AND item.status = 'RUNNING'
  AND ((#{operationId} IS NULL AND item.rerun_operation_id IS NULL)
    OR (#{operationId} IS NOT NULL
      AND item.rerun_operation_id = #{operationId}
      AND item.rerun_status = 'RUNNING'
      AND item.rerun_execution_token = #{operationExecutionToken}
      AND EXISTS (
          SELECT 1
          FROM tb_ai_log_management_operation operation
          WHERE operation.id = #{operationId}
            AND operation.status = 'RUNNING'
            AND operation.execution_token = #{operationExecutionToken}
            AND operation.lease_until > #{now}
      )))

UPDATE tb_ai_log_ai_task_item
SET attempt_count = attempt_count + 1,
    evidence_hash = #{evidenceHash},
    evidence_snapshot_json = #{evidenceSnapshotJson},
    next_retry_time = NULL,
    update_time = #{now}
WHERE id = #{itemId}
  AND claim_token = #{claimToken}
  AND status = 'RUNNING'
  AND attempt_count = #{expectedAttemptCount}
  AND attempt_count < max_attempts

UPDATE tb_ai_log_ai_task_item
SET status = 'SUCCESS',

WHERE id = #{itemId}
  AND claim_token = #{claimToken}
  AND status = 'RUNNING'

UPDATE tb_ai_log_ai_task_item item
SET item.status = 'RUNNING',
    item.rerun_status = 'RUNNING',
    item.rerun_execution_token = #{operationExecutionToken},
    item.claim_token = #{claimToken},
    item.lease_owner = #{leaseOwner},
    item.lease_until = #{leaseUntil},
    item.started_time = #{now},
    item.update_time = #{now}
WHERE item.id = #{itemId}
  AND item.rerun_operation_id = #{operationId}
  AND item.rerun_status = 'WAITING'
  AND item.status = 'WAITING'
  AND EXISTS (
      SELECT 1
      FROM tb_ai_log_management_operation operation
      WHERE operation.id = #{operationId}
        AND operation.status = 'RUNNING'
        AND operation.execution_token = #{operationExecutionToken}
        AND operation.lease_until > #{now}
  )

UPDATE tb_ai_log_ai_task_item item
SET item.attempt_count = item.attempt_count + 1,
    item.evidence_hash = #{evidenceHash},
    item.evidence_snapshot_json = #{evidenceSnapshotJson},
    item.update_time = #{now}
WHERE item.id = #{itemId}
  AND item.claim_token = #{claimToken}
  AND item.rerun_operation_id = #{operationId}
  AND item.rerun_execution_token = #{operationExecutionToken}
  AND item.rerun_status = 'RUNNING'
  AND item.status = 'RUNNING'
  AND item.attempt_count = #{expectedAttemptCount}
  AND EXISTS (
      SELECT 1
      FROM tb_ai_log_management_operation operation
      WHERE operation.id = #{operationId}
        AND operation.status = 'RUNNING'
        AND operation.execution_token = #{operationExecutionToken}
        AND operation.lease_until > #{now}
  )

UPDATE tb_ai_log_ai_task_item
SET status = 'SUCCESS',
    rerun_status = 'SUCCESS',

WHERE id = #{itemId}
  AND claim_token = #{claimToken}
  AND rerun_operation_id = #{operationId}
  AND rerun_execution_token = #{operationExecutionToken}
  AND rerun_status = 'RUNNING'
  AND status = 'RUNNING'
  AND EXISTS (
      SELECT 1
      FROM tb_ai_log_management_operation operation
      WHERE operation.id = #{operationId}
        AND operation.status = 'RUNNING'
        AND operation.execution_token = #{operationExecutionToken}
        AND operation.lease_until > #{now}
  )

UPDATE tb_ai_log_ai_task_item
SET status = 'FAILED',
    rerun_status = 'FAILED',
    final_attempt_no = attempt_count,
    next_retry_time = NULL,
    input_token_count = input_token_count + COALESCE(#{failure.inputTokens}, 0),
    output_token_count = output_token_count + COALESCE(#{failure.outputTokens}, 0),
    total_token_count = total_token_count + COALESCE(#{failure.totalTokens}, 0),
    total_latency_millis = total_latency_millis + #{latencyMillis},
    claim_token = NULL,
    lease_owner = NULL,
    lease_until = NULL,
    last_error_code = #{failure.errorCode},
    last_error_message = #{failure.errorMessage},
    finish_time = #{now},
    update_time = #{now}
WHERE id = #{itemId}
  AND claim_token = #{claimToken}
  AND rerun_operation_id = #{operationId}
  AND rerun_execution_token = #{operationExecutionToken}
  AND rerun_status = 'RUNNING'
  AND status = 'RUNNING'
  AND EXISTS (
      SELECT 1
      FROM tb_ai_log_management_operation operation
      WHERE operation.id = #{operationId}
        AND operation.status = 'RUNNING'
        AND operation.execution_token = #{operationExecutionToken}
        AND operation.lease_until > #{now}
  )

UPDATE tb_ai_log_ai_task_item
SET status = 'FAILED',
    rerun_status = 'FAILED',
    final_attempt_no = NULL,
    claim_token = NULL,
    lease_owner = NULL,
    lease_until = NULL,
    next_retry_time = NULL,
    last_error_code = #{errorCode},
    last_error_message = #{errorMessage},
    finish_time = #{now},
    update_time = #{now}
WHERE id = #{itemId}
  AND claim_token = #{claimToken}
  AND rerun_operation_id = #{operationId}
  AND rerun_execution_token = #{operationExecutionToken}
  AND rerun_status = 'RUNNING'
  AND status = 'RUNNING'
  AND EXISTS (
      SELECT 1
      FROM tb_ai_log_management_operation operation
      WHERE operation.id = #{operationId}
        AND operation.status = 'RUNNING'
        AND operation.execution_token = #{operationExecutionToken}
        AND operation.lease_until > #{now}
  )
